"""Static, source-bound optimization chapter; JavaScript only adds inspection."""
from html import escape
import math
import re


def text(value):
    return escape(str(value))


def exact(value):
    return 'Not measured' if value is None else str(value)


def short(value, digits=6):
    return f'{float(value):.{digits}g}'.replace('-', '−')


def source_anchor(source_id):
    return 'opt-source-' + re.sub(r'[^A-Za-z0-9_-]', '-', source_id)


def source(source_id, label='Source'):
    return f'<a class="opt-source-link" href="#{source_anchor(source_id)}">{text(label)} <span aria-hidden="true">↗</span></a>'


def table(caption, headers, rows, klass=''):
    body=''.join('<tr>'+''.join('<td>'+text(v)+'</td>' for v in row)+'</tr>' for row in rows)
    return f'<div class="table-wrap opt-table {klass}" tabindex="0" role="region" aria-label="{text(caption)}"><table><caption>{text(caption)}</caption><thead><tr>'+''.join('<th scope="col">'+text(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+body+'</tbody></table></div>'


def state_table(states):
    rows=[]
    for s in states:
        value='' if s['native_J'] is None else f' data-opt-value="{s["native_J"]}"'
        parity='Separate live-J parity: verified.' if s['separate_live_objective_parity'] else 'No separate live-J parity claimed.'
        rows.append(f'<tr data-opt-state="{s["id"]}" data-opt-evidence="{text(s["evidence_status"])}" data-opt-source="{text(s["source_id"])}"><th scope="row">{s["id"]}</th><td>{text(s["label"])}<small>{"Native sequence" if s["native_trajectory"] else "Diagnostic branch"}</small><small class="opt-state-scope">{text(s["scope"])}</small></td><td class="opt-numeric"{value}>{text(exact(s["native_J"]))}</td><td>{text(s["status"])}<small>{parity}</small></td><td>{source(s["source_id"],s["source_id"])}</td></tr>')
    return '<div class="table-wrap opt-table" tabindex="0" role="region" aria-label="Every main4500 state and saved native objective"><table><caption>Every state: native weighted training J. S3 has no independent measurement.</caption><thead><tr><th scope="col">State</th><th scope="col">Role</th><th scope="col">Native J</th><th scope="col">Evidence status</th><th scope="col">Source</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'


def state_chart(states):
    ticks=''.join(f'<span style="left:{(i+6)/7*100:.8f}%" class="{"opt-tick-minor" if i in (-5,-3,-1) else ""}">10<sup>{i}</sup></span>' for i in range(-6,2))
    rows=[]
    for s in states:
        branch=not s['native_trajectory']
        if s['native_J'] is None:
            track='<span class="opt-unmeasured">NOT_MEASURED · no objective position</span>'
        else:
            left=(math.log10(s['native_J'])+6)/7*100
            track=f'<span class="opt-state-mark {"opt-diamond" if branch else ""}" style="left:{left:.10f}%" data-opt-mark="{s["id"]}" data-opt-plot-value="{s["native_J"]}" aria-hidden="true"></span>'
        rows.append(f'<div class="opt-state-row {"opt-branch" if branch else ""}" data-opt-row="{s["id"]}"><button type="button" data-opt-select="{s["id"]}" aria-pressed="{str(s["id"]=="S0").lower()}" aria-controls="opt-selection" disabled><strong>{s["id"]}</strong><span>{text(s["label"])}</span><small>{"Branch from "+("S1" if s["id"]=="S1c" else "S2") if branch else "Native sequence"}</small></button><div class="opt-state-track">{track}</div><span class="opt-state-number">{short(s["native_J"],7) if s["native_J"] is not None else "—"}</span></div>')
    return '<div id="opt-state-chart" class="opt-state-chart" data-opt-log-min="-6" data-opt-log-max="1" aria-label="Native J on a fixed logarithmic axis"><div class="opt-axis-head"><span>Lower native J ←</span><span>Fixed log₁₀ scale</span></div><div class="opt-state-axis"><div>'+ticks+'</div></div>'+''.join(rows)+'</div>'


def force_plot(pbe):
    models=[('END_MAIN','End of main','end'),('TERMINAL','Terminal','terminal'),('HISTORICAL_H','Historical H','historical')]
    upper=math.ceil(max(r[m] for r in pbe['regional_rows'] for m,_,_ in models)*20)/20
    parts=[]
    for row in pbe['regional_rows']:
        title='Near the minimum' if row['region']=='BASIN_LEFT' else 'Transition region'
        bars=''.join(f'<div class="opt-force-row"><span>{label}</span><div class="opt-force-track" aria-hidden="true"><span class="opt-force-fill opt-{kind}" style="width:{row[key]/upper*100:.10f}%"></span></div><strong data-opt-force-model="{key}" data-opt-force-region="{row["region"]}" data-opt-force-value="{row[key]}">{row[key]:.6f}</strong></div>' for key,label,kind in models)
        parts.append(f'<div class="opt-force-region"><h4>{title}</h4>{bars}</div>')
    return '<div class="opt-force-chart" data-opt-force-min="0" data-opt-force-max="'+str(upper)+'">'+''.join(parts)+f'<p class="opt-axis-note">Both regions use the same linear bar scale: 0–{upper:g} eV/Å. Lower is better. Values are block-averaged force RMSE.</p></div>'


def sources_registry(sources):
    entries=[]
    for s in sources:
        public=s.get('source_access')=='PUBLIC' and bool(s.get('url'))
        link=f'<a href="{text(s["url"])}">Open public source ↗</a>' if public else '<span class="opt-restricted">Restricted source · aggregate export only</span>'
        entries.append(f'<article class="opt-source-entry" id="{source_anchor(s["id"])}" tabindex="-1"><div class="opt-source-title"><h4>{text(s["id"])}</h4>{link}</div><p>{text(s["scope"])}</p><dl><dt>Source locator</dt><dd><code>{text(s["file"])}</code></dd><dt>SHA-256</dt><dd><code>{text(s["sha256"])}</code></dd><dt>Access</dt><dd>{text(s["access"])}</dd></dl></article>')
    return ''.join(entries)


def render(d):
    t=d['theory'];a=t['architecture'];obj=a['objective'];episode=t['main4500'];states=episode['states'];s0=states[0];s2=next(s for s in states if s['id']=='S2');cov=t['COV'];lin=t['linear_system'];tr=t['transport'];obs=d['observer'];end=obs['end_terminal'];pbe=end['pbe14'];t1=d['t1'];q=t1['qualification'];cp=t1['checkpoint_example'];long=obs['long_boundaries'];short_run=obs['short_main50'];recovery=obs['recovery']
    blocks=''.join(f'<div class="opt-parameter-block opt-parameter-{b["id"]}"><strong>{b["count"]}</strong><h3>{text(b["label"])}</h3><p>{text(b.get("factorization",b.get("definition","")))}</p></div>' for b in a['parameter_blocks'])
    rowq=table('Same ROW_EXACT_FIXED_D problem; every term is divided by 60. These values are not native J.',['State','Data loss ℓ','Ridge R','Q = ℓ + R','Q − Q*'],[[r['state'],short(r['data_loss'],12),short(r['ridge_penalty'],12),short(r['Q_fixed_D'],12),short(r['row_gap'],12)] for r in lin['row_loss_table']])
    short_table=table('Historical IXA main50 counterexample; saved rounded native J summary',['State','Native J','Evidence'],[[r['state'],r['native_J'],r['status']] for r in short_run['states']])
    native_table=table('XI saved checkpoint pair: native weighted training J, separate from external force error',['Checkpoint','Native J','Energy term','Force term','Radial penalty'],[[r['state'],r['native_J'],r['energy_loss'],r['force_loss'],r['radial_penalty']] for r in end['native_rows']])
    regional=table('PBE14 development: block-averaged force RMSE / eV/Å',['Region','END_MAIN','TERMINAL','Historical H'],[[r['region'],r['END_MAIN'],r['TERMINAL'],r['HISTORICAL_H']] for r in pbe['regional_rows']])
    cases=table('All fourteen saved PBE14 case scores; component force RMSE / eV/Å',['Geometry','Region','Block','END_MAIN','TERMINAL','Historical H'],[[r['candidate_id'],r['region'],r['block'],r['END_MAIN'],r['TERMINAL'],r['HISTORICAL_H']] for r in pbe['case_scores']])
    checkpoint=table('Opposite synthetic example: same CHECKPOINT_A policy in CONTROL_A and COV_A',['Arm','END_MAIN J','TERMINAL J','BEST J','BEST role','Sequence'],[[r['arm'],r['END_MAIN_J'],r['TERMINAL_J'],r['BEST_J'],r['BEST_role'],r['BEST_sequence']] for r in cp['rows']])
    qualify=table('Historical T1 engineering qualification: synthetic fixtures only',['Check','Saved result','Scope'],[
        ['Scientific status',t1['statuses']['visible_limit'],t1['statuses']['T1']],
        ['Native core assertions',f'{q["native_core_assertions"]} = {q["inherited_assertions"]} + {q["additional_assertions"]}','Inherited + additional checks'],
        ['Pipeline',f'{q["pipeline"]["pretraining_accepted"]} + {q["pipeline"]["main_accepted"]} = {q["pipeline"]["accepted_per_arm"]} accepted per arm','CONTROL_A and COV_A; synthetic coordinates and labels'],
        ['Baseline parity',f'{q["baseline_parity"]["accepted_states"]} accepted states','FROZEN, OFF and CONTROL_A: bitwise objectives, gradients, parameters and saved BFGS snapshots'],
        ['COV prefix parity',str(q['pipeline']['candidate_prefix_equal'])+' accepted states','First candidate divergence follows this shared prefix'],
        ['Reload',str(q['reload']['processes'])+' processes','Evaluation reload only; no qualified full BFGS resume'],
        ['Injected faults',f'{q["faults"]["unique_file_error_points"]} file-error points + {q["faults"]["unique_signal_crash_cases"]} signal/crash cases','No power-loss or independent-hardware claim'],
        ['Sanitizers','ASan · LeakSanitizer · UBSan; '+str(q['sanitizers']['diagnostic_count'])+' diagnostics','Qualified C++ tests; external BLAS/LAPACK/Fortran uninstrumented']])
    boundaries=table('Positive changes in ten long printed logs; short traces repeat part of the same evidence',['Seed','Allocation','Main cap','Positive changes','Repeated in short prefix'],[[r['seed'],r['branch'],r['main_steps'],r['positive_printed_increases'],r['duplicate_short_prefix_increases']] for r in long['rows']])
    limits=''.join('<h4>'+text(k.title())+'</h4><ul>'+''.join('<li>'+text(v)+'</li>' for v in values)+'</ul>' for k,values in d['limitations'].items())
    taxonomy=''.join('<dt>'+text(k)+'</dt><dd>'+text(v)+'</dd>' for k,v in d['evidence_taxonomy'].items())
    native_path=' <span aria-hidden="true">→</span> '.join('<span>'+s+'</span>' for s in episode['native_order'])
    first=end['native_rows'][0];last=end['native_rows'][1];balance=lin['signed_ridge_balance'];prox=t['prediction_prox']
    return f'''<section id="optimization" data-page class="page optimization-page" aria-labelledby="opt-title">
<div class="opt-hero">
 <div class="opt-hero-copy"><p class="eyebrow">12 / Inside the optimization</p><h1 id="opt-title">The fit is <br><em>not the finish.</em></h1><p class="lede">{text(d['subtitle'])}</p><p class="opt-hero-intro">A training run can improve between steps and still lose ground at a refit. Follow one measured boundary, separate the objective from the solve, and see how far a safer update has actually been checked.</p><a class="opt-text-link" href="#opt-episode">Inspect the saved boundary <span aria-hidden="true">↓</span></a></div>
 <aside class="opt-hero-evidence" aria-label="Two results with distinct evidence scopes"><p class="micro">One periodic refit · main {episode['boundary']['iteration']}</p><div class="opt-hero-ratio"><strong>{episode['S2_to_S0_ratio']:.6f}<span>×</span></strong><p>higher native training <i>J</i><br>from S0 to S2</p></div><div class="opt-before-after"><div><span>S0 · before</span><strong>{short(s0['native_J'],7)}</strong></div><span aria-hidden="true">→</span><div><span>S2 · refit</span><strong>{short(s2['native_J'],7)}</strong></div></div><p class="small">One recovered diagnostic; measured saved physical states. {source('theory.new_main4500')}</p><div class="opt-hero-candidate"><strong>{cov['percent_of_total_data_loss_removed']:.6f}%</strong><div><span>less saved-row data loss with the COV candidate</span><p>Not yet a real-data optimizer win.</p></div></div><p class="small">Fixed matrices only. Candidate native E/F and gradient: {text(cov['candidate_native_EF_or_gradient'])}. {source('theory.new_main4500','Candidate evidence')}</p></aside>
</div>
<div class="opt-page-index" aria-label="Optimization chapter contents"><a href="#opt-parameters">01 · The parameters</a><a href="#opt-episode">02 · The boundary</a><a href="#opt-checkpoints">03 · The checkpoint</a><a href="#opt-candidate">04 · The candidate</a><a href="#opt-evidence">05 · The evidence</a><a href="#opt-next-study">06 · The next question</a></div>
<p id="opt-load-status" class="opt-load-status" role="status">The complete results, diagrams and tables below are available without JavaScript. State controls become available when the saved payload loads.</p>

<section id="opt-parameters" class="opt-chapter" aria-labelledby="opt-parameters-title" tabindex="-1">
 <div class="opt-chapter-heading"><p class="eyebrow">01 / What is being fitted?</p><h2 id="opt-parameters-title">{a['nominal_parameters']} coordinates.<br><em>Several different spaces.</em></h2><p>The potential has a precise parameter count. A molecular geometry, its predicted energy and forces, and a scalar error are different objects.</p></div>
 <div class="opt-parameter-total" aria-label="{a['nominal_parameters']} equals {text(' plus '.join(str(b['count'])+' '+b['label'].lower() for b in a['parameter_blocks']))}"><span class="micro">Nominal parameter vector</span><strong>{a['nominal_parameters']}</strong><div class="opt-parameter-strip" aria-hidden="true">{''.join(f'<span class="opt-strip-{b["id"]}" style="flex:{b["count"]}"></span>' for b in a['parameter_blocks'])}</div><span>{a['linear_parameters']} linear coefficients when the radial part is fixed</span></div>
 <div class="opt-parameter-grid">{blocks}</div>
 <p class="chapter-source">{source('theory.public_template','Public model template')} · {source('theory.architecture_atlas','Reviewed architecture')} · {source('theory.architecture_bridge','Parameter definitions')}</p>
 <div class="opt-space-map"><div><span class="micro">Geometry</span><h3>{a['atoms']} atoms · {a['cartesian_coordinates']} Cartesian coordinates</h3><p>{a['generic_internal_coordinates']} local internal coordinates after translations and rotations, for an isolated nonlinear regular geometry.</p></div><span class="opt-map-arrow" aria-hidden="true">→</span><div><span class="micro">Prediction</span><h3>Energy and Cartesian forces</h3><p>The parameterized potential maps a geometry to E and F. Fitting includes both in weighted training rows.</p></div><span class="opt-map-arrow" aria-hidden="true">→</span><div><span class="micro">Assessment</span><h3>J, row loss, or force RMSE</h3><p>Each answers a different question. Their definitions and units travel with every comparison below.</p></div></div>
 <details class="opt-details"><summary>The objective, the 210-dimensional flag, and the qualified 240 bound</summary><div class="opt-details-body"><h3>The training convention</h3><p class="opt-formula">{text(obj['native_formula'])}</p><p>{text(obj['scope'])}</p><p>There are {obj['energy_rows']} energy rows and {obj['force_rows']} force rows, {obj['weighted_rows']} total: energy residuals divided by 3, force residuals multiplied by 0.1. The row loss is <code>ℓ = ‖Aβ − y‖² / {obj['normalization_configurations']}</code>. The inner ridge problem adds <code>βᵀDβ / {obj['normalization_configurations']}</code> to give Q<sub>D</sub>. Native J also contains its own radial penalty. External force RMSE is reported separately in eV/Å.</p><h3>Known symmetries, stated locally</h3><p>The three radial channels form a {a['radial_channel_shape'][0]} × {a['radial_channel_shape'][1]} array. For rank-three channels, the nested flag <code>{text(a['flag'])}</code> has dimension <code>{text(a['flag_dimension_calculation'])}</code>. Removing the {a['known_channel_gauge_dimension']} identified channel-gauge dimensions and {a['known_offset_null_dimension']} fixed-composition offset-null dimensions gives {a['known_quotient_dimension']} local quotient coordinates.</p><p>{text(a['quotient_scope'])}</p><p>{text(a['auxiliary_state'])}</p><p>{source('theory.native_loss_source','Objective source')} · {source('theory.proof_register','Conditional proof register')} · {source('theory.offset_subspace_caveat','Offset subspace caveat')}</p></div></details>
</section>

<section id="opt-episode" class="opt-chapter" aria-labelledby="opt-episode-title" tabindex="-1">
 <div class="opt-chapter-heading"><p class="eyebrow">02 / A boundary you can inspect</p><h2 id="opt-episode-title">The refit changes the problem<br><em>inside the step.</em></h2><p>Main {episode['boundary']['iteration']}, refit {episode['boundary']['refit']}, in one {episode['boundary']['cap']}-step run. The logged jump is S0 → S4. The much larger temporary S1 value is a different event.</p></div>
 <div class="opt-native-path"><span class="micro">Native sequence</span><div>{native_path}</div><p>Separate diagnostic copies: S1 → S1c · S2 → S2q. They are branches, not accepted optimizer steps.</p></div>
 <div class="opt-episode-layout"><div class="panel opt-episode-panel"><div class="panel-heading"><span class="micro">Saved native J · lower is better</span><span class="badge">Weighted objective</span></div>{state_chart(states)}<div class="opt-mark-legend"><span><i class="opt-legend-native" aria-hidden="true"></i>Native state</span><span><i class="opt-legend-branch" aria-hidden="true"></i>Diagnostic copy</span><span>S3: no plotted value</span></div><div class="opt-playback" role="group" aria-label="Inspect saved states"><button type="button" id="opt-play" aria-pressed="false" disabled>Play native sequence</button><button type="button" id="opt-reset" disabled>Reset to S0</button><button type="button" id="opt-prev" aria-label="Previous state in reader order" disabled>← Previous</button><button type="button" id="opt-next" aria-label="Next state in reader order" disabled>Next →</button></div><p class="opt-control-help">Previous, Next and arrow keys inspect all seven rows in reader order; Home and End jump to its ends. Play follows the five native states only, once. No objective values are interpolated.</p></div>
 <aside id="opt-selection" class="opt-selection" aria-live="polite" aria-atomic="true" data-opt-selected="S0"><p class="micro" id="opt-selected-role">Native sequence · S0</p><h3 id="opt-selected-title">{text(s0['label'])}</h3><div class="opt-selected-value"><span>Native J</span><strong id="opt-selected-value">{text(exact(s0['native_J']))}</strong></div><p id="opt-selected-scope">{text(s0['scope'])}</p><p class="opt-evidence-tag" id="opt-selected-evidence">{text(s0['evidence_status'])}</p><p class="opt-status-code" id="opt-selected-status">{text(s0['status'])}</p><p id="opt-selected-source">{source(s0['source_id'],s0['source_id'])}</p><p class="small" id="opt-selected-source-field">Field: {text(s0['source_field'])}</p><p class="small" id="opt-selected-live">Separate live objective parity: verified.</p></aside></div>
 {state_table(states)}
 <div class="opt-native-deltas"><div><span>S0 → S2 · refit</span><strong>+{short(episode['native_telescope']['S0_to_S2'],9)}</strong></div><div><span>S2 → S4 · accepted search</span><strong>{short(episode['native_telescope']['S2_to_S4'],9)}</strong></div><div><span>S0 → S4 · logged change</span><strong>+{short(episode['native_telescope']['S0_to_S4'],9)}</strong></div></div><p class="small">Native J differences in one diagnostic; they are not a unique causal allocation to BFGS or refitting. {source('theory.new_main4500','Boundary evidence')}</p>
 <details class="opt-details"><summary>Why compensation works, and why a precise solve does not remove the jump</summary><div class="opt-details-body"><h3>S1c: preserve the physical function</h3><p class="opt-formula">Φ₁ = TΦ₀ &nbsp; · &nbsp; A₁ = A₀Tᵀ &nbsp; · &nbsp; β₁c = T⁻ᵀβ₀</p><p>{tr['exact_identities']} finite-graph identities, {tr['formal_monomials']} formal monomials and {tr['nonzero_transport_entries']} nonzero transport entries were checked. The determinant is <code>{text(tr['determinant'])}</code>. This assumes an invertible lower-triangular channel map on the specific L12 graph; force equality also requires a smooth geometry region.</p><p>On the source-verified Train60 points, the maximum energy difference was {short(tr['energy_maxabs_difference_eV'],9)} eV and the maximum force-component difference {short(tr['force_maxabs_difference_eV_per_A'],9)} eV/Å. Every component met <code>{text(tr['component_bound'])}</code>. The radial penalty changes, so this does not assert full-J gauge invariance or accuracy on unseen geometries. {source('theory.exact_math','Exact transport')} · {source('theory.new_main4500','Physical parity')}</p><h3>S2q: name the system before naming its error</h3><p>The new S2q copy solves <strong>ROW_EXACT_FIXED_D</strong>: exact scalar products of the saved binary64 A and y, with D reconstructed from the reviewed native operations. It is not the optimum of the separately captured native K. The native solver uses Gaussian elimination without pivoting.</p><ul>{''.join('<li><strong>'+text(r['id'])+'</strong>: '+text(r['definition'])+'</li>' for r in lin['systems'])}</ul><p>The ACTUAL_K_CAPTURE solve gap is {short(lin['solver_gap_on_ACTUAL_K_CAPTURE'],12)}, divided by 60. A residual formed first in float64 overestimates that gap by {short(lin['float_residual_gap_divided_by_resolved_gap'],9)}×. The row-system gap at the effective native coefficients is {short(lin['total_effective_beta_gap_on_ROW_EXACT_FIXED_D'],12)}. Row-Q minus captured-Q, {short(lin['row_Q_minus_captured_Q'],12)}, compares different problems and is not a solve gap.</p><p>Solutions were cross-checked at {lin['precision_digits'][0]} and {lin['precision_digits'][1]} digits with LU and Cholesky. Agreement resolves this numerical comparison; it is not an interval certificate. The measured S2q − S2 native-J change is only {short(episode['S2q_minus_S2_native_J'],12)}.</p>{rowq}<h3>A signed balance in one fixed row problem</h3><p class="opt-formula">ℓ(S2) − ℓ(S1c) = −[Q(S1c) − Q*] + [R(S1c) − R(S2)] + [Q(S2) − Q*]</p><p class="opt-balance-values">{short(balance['data_change_S2_minus_S1c'],12)} = −{short(balance['regularized_improvement_from_compensated'],12)} + {short(balance['ridge_tradeoff'],12)} + {short(balance['effective_native_solver_row_gap'],12)}</p><p>The data term increases while the fixed-D ridge problem improves. This accounting is a signed equality in one problem, not a percentage attribution of physical causes. {source('theory.new_main4500','Systems, precision checks and exact decimal rows')} · {source('theory.numerical_policy','Frozen numerical policy')}</p></div></details>
 <div class="opt-context-pair"><div><p class="micro">A broader printed-log observation</p><h3>{long['positive_printed_increases']:,} increases<br>at {long['boundary_period']}-step boundaries</h3><p>Across {long['long_logs']} long logs: {long['data_allocations']} fixed allocations × {long['paired_optimizer_seeds']} paired optimizer seeds. The short prefixes repeat {long['duplicate_short_prefix_increases']} of these increases; they are not added again.</p><p class="small">Counts of printed changes are not independent causal experiments. H/A/B/C reproduce one observable seed trajectory, not four scientific replicates. {source(long['source_id'])}</p></div><div><p class="micro">The counterexample stays visible</p><h3>At short-run main {short_run['main_iteration']},<br>the refit improves J.</h3><p>S0 → S2: {short(short_run['base_change_J'],10)}.<br>S2 → S4: {short(short_run['search_change_J'],10)}.</p><p class="small">Periodic refits are not uniformly harmful. This is an exactly recovered historical reader with rounded summary values, not a new main50 physical replay. {source(short_run['source_id'])}</p></div></div>
 <details class="opt-details"><summary>Read the ten-log recount, the opposite main50 example, and recovery cost</summary><div class="opt-details-body">{boundaries}{short_table}<h3>What was recovered</h3><p>{recovery['real_diagnostic_training_runs']} real diagnostic training process ({recovery['training_pretraining_steps']} pretraining + {recovery['training_main_steps']} main steps; {recovery['training_printed_rows']} printed rows) and {recovery['detached_physical_replays']} detached physical replays. All six final replay checks pass. The {recovery['historical_live_result_byte_matches']} historical live-state result files ({', '.join(recovery['historical_live_states'])}) match byte for byte. S1c and S2q are new derived copies.</p><p>The original M01 archive and old raw journal remain missing. New process/runtime receipts establish this recovery's provenance; they do not restore a missing historical journal. This recovery is separate from synthetic T1 and is not a COV optimizer experiment.</p><p>There were {recovery['new_COV_candidate_physical_evaluations']} COV candidate physical evaluations, {recovery['new_T2_runs']} T2 runs, {recovery['new_DFT_runs']} new DFT runs, {recovery['new_MD_runs']} MD runs and {recovery['new_protected_holdout_model_evaluations']} protected-holdout model evaluations. {source(recovery['source_id'],'Recovery ledger')}</p></div></details>
</section>

<section id="opt-checkpoints" class="opt-chapter" aria-labelledby="opt-checkpoints-title" tabindex="-1">
 <div class="opt-chapter-heading"><p class="eyebrow">03 / Which finished model?</p><h2 id="opt-checkpoints-title">The last file can be<br><em>the weaker checkpoint.</em></h2><p>One saved XI / XI-T Basin60, seed-{end['seed_index']} pair separates the end of main optimization from the terminal model. Checkpoint policy belongs in the comparison.</p></div>
 <div class="opt-checkpoint-layout"><div class="opt-checkpoint-native"><span class="micro">Native weighted training J</span><strong class="opt-checkpoint-ratio">{end['terminal_over_end_main']:.6f}<span>×</span></strong><h3>Terminal / end of main</h3><dl><dt>END_MAIN</dt><dd>{short(first['native_J'],10)}</dd><dt>TERMINAL</dt><dd>{short(last['native_J'],10)}</dd></dl><p>Lower J at END_MAIN for this saved pair. {source('OBS_XIT_TRAIN_CONTRAST','Native comparison')}</p><p class="small">One trajectory, {end['cost_scope']['XI_main_steps']} main steps versus {end['cost_scope']['H_main_steps']} for historical H. This is not a cost-matched optimizer comparison.</p></div><div class="panel opt-checkpoint-force"><div class="panel-heading"><h3>PBE14 development forces</h3><span class="micro">eV/Å · lower is better</span></div>{force_plot(pbe)}<p>END_MAIN has lower regional error than TERMINAL in both regions. Against historical H, it improves the transition region and worsens the basin.</p><p class="small">{pbe['end_better_blocks']}/{pbe['blocks']} blocks and {pbe['end_better_cases']}/{pbe['configurations']} cases favor END_MAIN over TERMINAL; {', '.join(pbe['end_worse_cases'])} do not. {source(pbe['source_id'],'Force-score evidence')}</p></div></div>
 <p class="opt-visible-limit">PBE14 was already used for development. TERMINAL's raw prediction vectors are missing: its saved fourteen error scores can be reaggregated. The historical XI journal is still missing, and XI-T P1's runtime-capture status remains <strong>FAIL_STOP_NO_RETRY</strong>.</p>
 <details class="opt-details"><summary>Exact checkpoint terms, fourteen force scores, and their evidence tiers</summary><div class="opt-details-body">{native_table}{regional}<p>{text(pbe['aggregation'])}</p><ul>{''.join('<li><strong>'+text(k)+'</strong>: '+text(v)+'</li>' for k,v in pbe['evidence_by_model'].items())}</ul>{cases}<p>The P1 numeric process exited zero, but no actual-runtime snapshot was captured. Its saved negative receipt remains unchanged. The new C-long recovery does not repair XI chronology or isolate the terminal operation contributions. {source('OBS_XIT_GATE','Historical gate')} · {source('OBS_XI_PILOT_GATE','Pilot scope')}</p></div></details>
 <div class="opt-opposite-checkpoint"><p class="micro">The opposite result · synthetic T1</p><h3>Here, BEST is TERMINAL—in both arms.</h3><p>{text(cp['interpretation'])} Both arms use the same {text(cp['policy'])} policy: {text(cp['selection_rule'])}.</p>{checkpoint}<p class="chapter-source">{source('t1-pipelines','Synthetic pipeline evidence')} · {source('t1-checkpoint-policy','Checkpoint policy')} · Model reload supports evaluation; it is not full BFGS continuation.</p></div>
</section>

<section id="opt-candidate" class="opt-chapter" aria-labelledby="opt-candidate-title" tabindex="-1">
 <div class="opt-chapter-heading"><p class="eyebrow">04 / A candidate with a narrower guarantee</p><h2 id="opt-candidate-title">Preserve the function.<br><em>Regularize the change.</em></h2><p>After coefficient compensation, choose an increment in the fixed-composition feasible space. A fixed row problem gives a precise data-loss guarantee.</p></div>
 <div class="opt-cov-layout"><div class="opt-cov-math"><span class="micro">Fixed A and M · constrained COV</span><p class="opt-cov-formula">δ = T<sub>g</sub>z</p><p class="opt-formula">min<sub>z</sub> ‖r + AT<sub>g</sub>z‖² + δᵀMδ</p><p>T<sub>g</sub> has {cov['regularized_stack_shape'][1]} feasible columns: one composition-weighted offset direction and the invariant coefficients. For an already chosen metric, <code>M = T D₀ Tᵀ</code>.</p><p>The exact constrained minimizer cannot increase the saved-row data loss because zero is feasible and the penalty is nonnegative. This theorem assumes fixed A, r, feasible space and positive M on that space.</p><p>{source('theory.proof_register','Conditional theorem')} · {source('theory.new_main4500','One saved-row check')}</p></div><aside class="opt-cov-result"><span class="micro">One saved-row calculation</span><strong>{cov['percent_of_total_data_loss_removed']:.6f}<span>%</span></strong><h3>of the whole data loss removed</h3><dl><dt>Compensated incumbent ℓ</dt><dd>{short(cov['data_loss_incumbent'],12)}</dd><dt>Candidate ℓ</dt><dd>{short(cov['candidate_data_loss_saved_matrix_only'],12)}</dd><dt>Saved-row decrease</dt><dd>{short(cov['data_loss_decrease'],12)}</dd></dl><p class="opt-evidence-tag">DERIVED_SAVED_ARITHMETIC</p><p>Native E/F and gradient: <strong>{text(cov['candidate_native_EF_or_gradient'])}</strong>. External accuracy: <strong>{text(cov['off_training_accuracy'])}</strong>. No candidate potential was exported.</p></aside></div>
 <div class="opt-transaction" aria-label="Conceptual future runtime transaction, not an executing optimizer"><div><span>01</span><h4>Construct candidate</h4><p>Fixed-space increment around the compensated incumbent.</p></div><div><span>02</span><h4>Evaluate native J</h4><p>A separate runtime check of the original objective.</p></div><div><span>03</span><h4>Accept if qualified</h4><p>Apply the fixed numerical tolerance and checkpoint policy.</p></div><div><span>04</span><h4>Otherwise, full rollback</h4><p>Restore the complete required optimizer state.</p></div></div><p class="opt-axis-note">Conceptual transaction. No optimizer, potential evaluation, fitting or physics calculation runs in this page.</p>
 <details class="opt-details"><summary>Projected stationarity, metric transport, and the prediction-prox alternative</summary><div class="opt-details-body"><p class="opt-formula">{text(cov['projected_stationarity'])}</p><p>Stationarity is projected onto the feasible space; a full unprojected zero gradient is not required. The normalized projected residual is {short(cov['projected_stationarity_normalized'],10)}. The QR/SVD prediction discrepancy is {short(cov['QR_SVD_prediction_maxabs'],10)}.</p><p class="opt-formula">{text(cov['descent_identity'])}</p><p>The absolute identity residual is {short(cov['descent_identity_absolute_residual'],10)}. The {cov['regularized_stack_shape'][0]} × {cov['regularized_stack_shape'][1]} regularized stack has condition number {short(cov['regularized_stack_condition_number'],10)} and the coefficient increment norm is {short(cov['coefficient_increment_l2'],10)}. These checks describe this saved calculation, not external force accuracy.</p><p>{text(cov['D0_origin'])}. {text(cov['covariance_scope'])}</p><h3>Prediction-prox: distinguish the two denominators</h3><p>At λ = {prox['lambda']:g}, {prox['fraction_of_available_gap_removed']*100:g}% of the <em>available projected least-squares gap</em> is removed. That is {prox['percent_of_total_data_loss_removed']:.6f}% of the whole incumbent loss. It is not a 75% reduction of total loss. The coefficient increment norm is {short(prox['coefficient_increment_l2'],10)}; numerical rank selection remains a caveat. Native E/F and off-training qualification are absent here too.</p><p>Along the native ridge direction, the unconstrained optimum is α = {short(prox['native_ridge_direction']['unconstrained_alpha'],10)}; the best α in [0, 1] is {prox['native_ridge_direction']['best_alpha_on_0_1']:g}. This is a saved-row directional calculation, not an executed line search. {source('theory.new_main4500','Detailed saved arithmetic')}</p></div></details>
</section>

<section id="opt-evidence" class="opt-chapter" aria-labelledby="opt-evidence-title" tabindex="-1">
 <div class="opt-chapter-heading"><p class="eyebrow">05 / How far the claim travels</p><h2 id="opt-evidence-title">A theorem, an engineering check,<br><em>and a test still ahead.</em></h2><p class="opt-required-limit">{text(t1['statuses']['visible_limit'])}</p></div>
 <div class="opt-evidence-rail"><article class="opt-gate opt-gate-theory"><span class="opt-gate-code">T0</span><span class="micro">Conditional mathematics</span><h3>Theory verified</h3><p>Finite-graph transport and fixed-space inequalities, with their assumptions. One source-verified diagnostic illustrates them.</p><p class="opt-status-code">{text(d['scope']['T0_status'])}</p><p>{source('theory.proof_register','T0 scope')}</p></article><article class="opt-gate opt-gate-engineering"><span class="opt-gate-code">T1</span><span class="micro">Synthetic engineering</span><h3>Qualification passed</h3><p>{q['fixture']['configurations']} configurations × {q['fixture']['atoms_per_configuration']} atoms, with synthetic coordinates and labels. Native transaction and checkpoint behavior checked.</p><p class="opt-status-code">{text(t1['statuses']['T1'])}</p><p>{source(q['source_id'],'T1 gate')}</p></article><article class="opt-gate opt-gate-future"><span class="opt-gate-code">T2</span><span class="micro">Future · untested</span><h3>Comparison not run</h3><p>A locked, cost-matched real-data optimizer comparison and independent external physical validation are still required.</p><p class="opt-status-code">{text(t1['statuses']['T2'])}</p><p>No authorization. No execution.</p></article></div>
 {qualify}
 <p class="chapter-source">{source('t1-native-assertions','94 assertions')} · {source('t1-pipelines','Pipeline')} · {source('t1-reload','Reload checks')} · {source('t1-faults','Fault cases')} · {source('t1-sanitizer','Sanitizer scope')}</p>
 <details class="opt-details"><summary>Read the engineering limits and the separate recovery ledger</summary><div class="opt-details-body"><p>The earlier T1 status {text(t1['statuses']['prior'])} remains part of the record. The final pass does not retroactively change failed or incomplete historical gates or unknown prototype counters.</p><p>Evaluation reload has maximum objective and gradient errors {q['reload']['objective_max_abs_error']} and {q['reload']['gradient_max_abs_error']}, and weighted E/F vector error {short(q['reload']['weighted_EF_max_abs_error'],10)}. That vector uses energy / 3 and force × 0.1; it is not force RMSE. Full BFGS resume is unqualified.</p><p>File-error injection and real signal/crash cases do not certify power-loss durability. Two copies on one filesystem are not independent hardware replicas. SHA checks byte integrity, not ownership authentication or protection against valid stale-history rollback.</p><p>Historical synthetic T1 reports zero real Train60 fits and real replays in that scope. The later authorized missing-input recovery has one real training process and six physical replays, separately recorded. Neither is a real-data COV optimizer comparison. {source('t1-counters','Historical T1 counters')} · {source('t1-context-new-recovery','Separate recovery')}</p></div></details>
</section>

<section id="opt-next-study" class="opt-chapter opt-next-study" aria-labelledby="opt-next-title" tabindex="-1"><div><p class="eyebrow">06 / The next testable question</p><h2 id="opt-next-title">A safer update is a candidate.<br><em>Does it win a fair comparison?</em></h2></div><div><p>Use the same locked checkpoint policy, data allocations, seeds and cost accounting in both arms. Then assess independent physical errors beyond the development examples. That study has not been authorized or executed.</p><p>Until then, the evidence supports a precise diagnosis, a conditional saved-row guarantee and synthetic engineering qualification. It does not establish better real-data optimization or safe molecular dynamics.</p><div class="opt-next-links"><a href="#seeds">Seed sensitivity ↗</a><a href="#offpath">Off the path ↗</a><a href="#train119">Applicability limits ↗</a><a href="#reproduce">Reproduce the public arithmetic ↗</a></div></div></section>

<section id="opt-sources" class="opt-source-section" aria-labelledby="opt-sources-title" tabindex="-1"><div class="opt-chapter-heading"><p class="eyebrow">Evidence that travels with the figure</p><h2 id="opt-sources-title">Inspect the sources.<br><em>Keep their access boundaries.</em></h2><p>{text(d['scope']['public_reproduction'])}</p></div><div class="opt-downloads"><a class="button" href="data/optimization/OPTIMIZATION_STORY.json" download>Aggregate payload ↓</a><a class="button" href="data/optimization/CLAIM_DATA_MAP.tsv" download>Claim-to-data map ↓</a><a class="button" href="data/optimization/PROVENANCE.json" download>Provenance ↓</a><a class="button" href="data/optimization/PUBLICATION_ALLOWLIST.json" download>Publication scope ↓</a><a class="button" href="data/optimization/README.md" download>Reproduction notes ↓</a></div><details class="opt-details"><summary>Evidence taxonomy and all stated limitations</summary><div class="opt-details-body"><dl class="opt-taxonomy">{taxonomy}</dl>{limits}<h4>Not proved</h4><ul>{''.join('<li>'+text(v)+'</li>' for v in t['proof_scope']['not_proved'])}</ul></div></details><details id="opt-source-registry" class="opt-details opt-registry"><summary>Full source registry · {len(d['sources'])} source identities and SHA-256 values</summary><div class="opt-details-body"><p>Public entries link to existing public files. Restricted locators identify reviewed private evidence; they are not downloads. The public payload exposes selected aggregate values and their claim bindings.</p>{sources_registry(d['sources'])}</div></details><p class="small opt-edition">{text(d['edition'])} · {text(d['schema'])} · No new scientific calls by the site build.</p></section>
</section>'''


def extend_document(document, d):
    if 'id="optimization"' in document:
        raise ValueError('Duplicate optimization section')
    if d.get('schema') != 'proton-optimization-v1':
        raise ValueError('Unsupported optimization payload')
    old='Everything displayed here can be reconstructed from saved public files.'
    new='The original public studies can be reconstructed from their saved public files. The optimization chapter publishes selected aggregates and table arithmetic; restricted native evidence is identified by source locator and SHA-256 and is not distributed here.'
    if document.count(old)!=1:
        raise ValueError('Reproduction-scope sentence is not uniquely identified')
    document=document.replace(old,new,1)
    document=document.replace('</head>','<link rel="stylesheet" href="optimization.css"><script type="module" src="optimization.mjs"></script></head>',1)
    document=document.replace('</nav>','<a href="#optimization" data-route="optimization">Optimization <span aria-hidden="true">↗</span></a></nav>',1)
    return document.replace('</main>',render(d)+'</main>',1)
